import json
import re
import sys

destinationOrganizationMoid = ""
# HTTP evidence is independent from strict organization identity inspection.
# The connector contract supplies an integral HTTP status and Boolean success.
try:
    httpStatus = int(sys.argv[4])
except (ValueError, TypeError):
    httpStatus = 0
requestSucceeded = sys.argv[5].strip().lower() == "true"
if not requestSucceeded or httpStatus != 200:
    statusCode = httpStatus if 300 <= httpStatus < 600 else 502
    lookupStatus = "api-failure"
    message = "Organization lookup API request failed"
    errorMessage = "The organization request failed or returned a non-200 response."
    organizationMoid, organizationJson, inspectionComplete = "", "{}", False
    safeCode, safeMessage = "", ""
    try:
        payload = json.loads(sys.argv[1])
        # Preserve the native String projection used by the old safe allowlists.
        def text(value):
            return value if isinstance(value, str) else json.dumps(value, separators=(",", ":"), ensure_ascii=False)
        code = text(payload["Code"]) if isinstance(payload, dict) and "Code" in payload else ""
        detail = text(payload["Message"]) if isinstance(payload, dict) and "Message" in payload else ""
        if re.fullmatch(r"[A-Za-z0-9_.:-]{1,128}", code):
            safeCode = code
        if re.fullmatch(r"[A-Za-z0-9 _.,:()/+\-]{1,500}", detail) and not re.search(r"authorization|password|secret|token|api.?key|bearer|https?://", detail, re.IGNORECASE):
            safeMessage = detail
    except Exception:
        pass
    if safeMessage:
        errorMessage = safeMessage
    resultJson = json.dumps({"status":"api-failure", "upstreamStatus":httpStatus, "Code":safeCode, "Message":safeMessage}, separators=(",", ":"))
else:
    import json
    import re
    import sys
    statusCode, lookupStatus, message = 502, "invalid-response", "Organization response is invalid"
    organizationMoid, organizationJson = "", "{}"
    inspectionComplete = False
    try:
        payload = json.loads(sys.argv[1])
        if not isinstance(payload, dict): raise ValueError("Organization response must be an object")
        count, rows = payload.get("Count"), payload.get("Results")
        if isinstance(count, bool) or not isinstance(count, int) or count < 0: raise ValueError("Count must be a nonnegative integer")
        if not isinstance(rows, list): raise ValueError("Results must be an array")
        if count != len(rows): raise ValueError("Count and Results length differ; the bounded page is incomplete")
        if count > 3: raise ValueError("Count exceeds the three-row lookup bound")
        requested = [("Template", sys.argv[2]), ("Destination", sys.argv[6])]
        names = {name for role, name in requested}
        matches = {name: [] for name in names}
        for item in rows:
            if not isinstance(item, dict) or item.get("Name") not in names:
                raise ValueError("Organization Name does not match either requested name exactly")
            if item.get("ObjectType") != "organization.Organization" or item.get("ClassId") != "organization.Organization":
                raise ValueError("Organization discriminators do not match")
            moid = item.get("Moid")
            pattern = r"[0-9a-fA-F]{24}" if sys.argv[3] == "Hex24" else r"[A-Za-z0-9][A-Za-z0-9._~-]{0,127}"
            if not isinstance(moid, str) or re.fullmatch(pattern, moid) is None:
                raise ValueError("Organization Moid is missing or malformed")
            matches[item["Name"]].append(item)
        missing = next(((role, name) for role, name in requested if not matches[name]), None)
        if any(len(items) > 1 for items in matches.values()):
            statusCode, lookupStatus, message = 409, "ambiguous", "More than one organization matched an exact requested name"
        elif len(names) == 2 and len(rows) == 2 and rows[0]["Moid"] == rows[1]["Moid"]:
            raise ValueError("Different organization names returned the same Moid")
        elif missing:
            statusCode, lookupStatus = 404, "not-found"
            message = "%s organization '%s' was not found or is not accessible" % missing
        else:
            item = matches[sys.argv[2]][0]
            organizationMoid = item["Moid"]
            destinationOrganizationMoid = matches[sys.argv[6]][0]["Moid"]
            projected = {key:item[key] for key in ("Moid", "Name", "ObjectType", "ClassId")}
            organizationJson = json.dumps(projected, separators=(",", ":"))
            resultJson = json.dumps({"Count":1,"Results":[projected]}, separators=(",", ":"))
            statusCode, lookupStatus, message = 200, "exact", "Template and destination organizations resolved exactly"
        inspectionComplete = True
    except Exception as exc:
        statusCode, lookupStatus, message, inspectionComplete = 502, "invalid-response", str(exc), True
    errorMessage = "" if statusCode == 200 else message
    if statusCode != 200: resultJson = json.dumps({"status":lookupStatus,"error":message}, separators=(",", ":"))

import json
import re
import sys
statusCode = 502
statusMessage, errorMessage, resultJson = sys.argv[3:6]
try:
    upstream = int(sys.argv[2])
except (ValueError, TypeError):
    upstream = 0
try:
    payload = json.loads(sys.argv[1])
    def text(value):
        return value if isinstance(value, str) else json.dumps(value, separators=(",", ":"))
    code = text(payload["Code"]) if isinstance(payload, dict) and "Code" in payload else ""
    message = text(payload["Message"]) if isinstance(payload, dict) and "Message" in payload else ""
    if re.fullmatch(r"[A-Za-z0-9_.:-]{1,128}", code):
        def populate(template):
            return template.replace("{code}", code).replace("{message}", message)
        errorMessage, resultJson = populate(sys.argv[6]), populate(sys.argv[7])
        if re.fullmatch(r"[A-Za-z0-9 _.,:()/+\-]{1,500}", message) and not re.search(r"authorization|password|secret|token|api.?key|bearer|https?://", message, re.IGNORECASE):
            errorMessage, resultJson = populate(sys.argv[8]), populate(sys.argv[9])
except Exception:
    pass
if 300 <= upstream < 600:
    statusCode = upstream
statusText = str(statusCode)

